# Expose top level functions
Unit = naturaldate.Unit
activate = naturaldate.activate
apnumber = naturaldate.apnumber
clamp = naturaldate.clamp
deactivate = naturaldate.deactivate
fractional = naturaldate.fractional
get_translation = naturaldate.get_translation
intcomma = naturaldate.intcomma
intword = naturaldate.intword
naturaldate = naturaldate.naturaldate
naturalday = naturaldate.naturalday
naturaldelta = naturaldate.naturaldelta
naturalsize = naturaldate.naturalsize
naturaltime = naturaldate.naturaltime
ordinal = naturaldate.ordinal
precisedelta = naturaldate.precisedelta
current = naturaldate.current
scientific = naturaldate.scientific
metric = naturaldate.metric
def naturaldate.Unit():
    return Unit

def activate():
    return activate

def apnumber(number):
    return apnumber(number)

def clamp(number, min=None, max=None):
    return clamp(number, min, max)

def deactivate():
    return deactivate

def fractional(number):
    return fractional(number)

def get_translation(word):
    return get_translation(word)

def intcomma(number, ndigits=0):
    return intcomma(number, ndigits)

def intword(number):
    return intword(number)

def naturaldate(date):
    return naturaldate(date)

def naturalday(date):
    return naturalday(date)

def naturaldelta(delta):
    return naturaldelta(delta)

def naturalsize(size):
    return naturalsize(size)

def naturaltime(time):
    return naturaltime(time)

def ordinal(number):
    return ordinal(number)

def precisedelta(delta):
    return precisedelta(delta)

def current(date):
    return current(date)
